import { describe, expect, it } from "vitest";
import {
  conditionMemorySummary,
  describeCondition,
  evaluateCondition,
  sessionPathsIn,
} from "./conditionPhrase";

describe("describeCondition", () => {
  it("phrases string equality", () => {
    expect(describeCondition("session.card_replace.replacement_reason == 'damaged'")).toEqual({
      path: "session.card_replace.replacement_reason",
      entry: "replacement_reason",
      verb: "is",
      value: "damaged",
    });
  });

  it("phrases inequality and boolean literals", () => {
    expect(describeCondition("session.travel_notice.notice_confirmed != True")).toEqual({
      path: "session.travel_notice.notice_confirmed",
      entry: "notice_confirmed",
      verb: "is not",
      value: "true",
    });
    expect(describeCondition("session.travel_notice.notice_confirmed == False")).toEqual({
      path: "session.travel_notice.notice_confirmed",
      entry: "notice_confirmed",
      verb: "is",
      value: "false",
    });
  });

  it("phrases negation and bare truthiness as set / not set", () => {
    expect(describeCondition("not session.project.selected_card_id")).toEqual({
      path: "session.project.selected_card_id",
      entry: "selected_card_id",
      verb: "is not",
      value: "set",
    });
    expect(describeCondition("session.travel_notice.destination_high_risk")).toEqual({
      path: "session.travel_notice.destination_high_risk",
      entry: "destination_high_risk",
      verb: "is",
      value: "set",
    });
  });

  it("falls back to null for compound or unphrasable expressions", () => {
    expect(describeCondition("session.a.b and not session.a.c")).toBeNull();
    expect(describeCondition("session.a.b == session.a.c")).toBeNull();
    expect(describeCondition("nonsense")).toBeNull();
  });
});

describe("conditionMemorySummary", () => {
  const memory = {
    "card_replace.replacement_reason": { value: "stolen" },
    "project.selected_card_id": { value: null },
  };

  it("shows only the values, one per referenced entry", () => {
    expect(
      conditionMemorySummary(
        "session.card_replace.replacement_reason == 'damaged' and not session.project.selected_card_id",
        memory,
      ),
    ).toBe("stolen\nnot set");
  });

  it("reports unknown entries as not set", () => {
    expect(conditionMemorySummary("session.travel_notice.destination", memory)).toBe("not set");
  });

  it("returns null without memory or memory paths", () => {
    expect(conditionMemorySummary("session.a.b", null)).toBeNull();
    expect(conditionMemorySummary("nonsense", memory)).toBeNull();
  });
});

describe("evaluateCondition", () => {
  const memory = {
    "card_replace.reason": { value: "stolen" },
    "project.selected_card_id": { value: "card-1" },
    "travel_notice.confirmed": { value: true },
  };

  it("evaluates string equality and inequality", () => {
    expect(evaluateCondition("session.card_replace.reason == 'stolen'", memory)).toBe(true);
    expect(evaluateCondition("session.card_replace.reason == 'damaged'", memory)).toBe(false);
    expect(evaluateCondition("session.card_replace.reason != 'damaged'", memory)).toBe(true);
  });

  it("evaluates boolean literals", () => {
    expect(evaluateCondition("session.travel_notice.confirmed == True", memory)).toBe(true);
    expect(evaluateCondition("session.travel_notice.confirmed != False", memory)).toBe(true);
  });

  it("evaluates is-set and is-not-set", () => {
    expect(evaluateCondition("session.project.selected_card_id", memory)).toBe(true);
    expect(evaluateCondition("not session.project.selected_card_id", memory)).toBe(false);
    expect(evaluateCondition("session.travel_notice.missing", memory)).toBe(false);
    expect(evaluateCondition("not session.travel_notice.missing", memory)).toBe(true);
  });

  it("treats a cleared (null) entry as not set", () => {
    const cleared = { "card_replace.reason": { value: null } };
    expect(evaluateCondition("session.card_replace.reason", cleared)).toBe(false);
    expect(evaluateCondition("not session.card_replace.reason", cleared)).toBe(true);
  });

  it("returns undefined for expressions beyond the phrase grammar", () => {
    expect(evaluateCondition("session.a.b and not session.a.c", memory)).toBeUndefined();
    expect(evaluateCondition("session.a.b == session.a.c", memory)).toBeUndefined();
    expect(evaluateCondition("nonsense", memory)).toBeUndefined();
  });

  it("returns undefined without memory", () => {
    expect(evaluateCondition("session.a.b", null)).toBeUndefined();
    expect(evaluateCondition("session.a.b", undefined)).toBeUndefined();
  });
});

describe("sessionPathsIn", () => {
  it("collects unique paths in source order", () => {
    expect(sessionPathsIn("session.a.b == session.a.c or session.a.b")).toEqual([
      "session.a.b",
      "session.a.c",
    ]);
  });
});
